    mode === "raw"
      ? `<pre class="dash-pre dash-pre--raw" tabindex="0">${EscapeHtml(j.markdown || "")}</pre>`
      : `<div class="dash-md-reader" tabindex="0">${MarkdownToSafeHtml(j.markdown || "")}</div>`;
  main.innerHTML = `
    <header class="dash-page-head dash-page-head--hi">
