    </header>
    <div class="dash-toggle-row" role="group" aria-label="View mode">
      <button type="button" class="dash-btn dash-btn--tab ${mode === "rendered" ? "dash-btn--tab-active" : ""}" data-human-mode="rendered">Rendered</button>
